
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ecmv92_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ecmv92", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.319391354486402e+00, -4.237544103327619e+00, -4.122967087858084e+00, -3.964484155462833e+00, -3.749031638756194e+00, -3.463353823273132e+00, -3.097952357895529e+00, -2.654113462355521e+00, -2.152607484182208e+00, -1.632246821315418e+00, -1.109062741912077e+00, -7.131197668530156e-01, -6.040652696978055e-01, -5.036727147907647e-01, -3.740048986789404e-01, -2.496370988075777e-01, -1.435357324761042e-01, -5.549815395563252e-02, -1.221276788417842e-02, -1.374339799918795e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


